class Solution:
    def minTime(self, timeReq: List[int], splitTime: int) -> int:
        import heapq
        t = sorted(timeReq, reverse=True)
        h = [splitTime]
        ans = 0
        for i, x in enumerate(t):
            c = heapq.heappop(h)
            ans = max(ans, c + x)
            if i + 1 < len(t):
                heapq.heappush(h, c + splitTime)
                heapq.heappush(h, c + splitTime)
        return ans

