class Solution {
public:
    long long minTime(vector<int>& timeReq, int splitTime) {
        sort(timeReq.rbegin(), timeReq.rend());
        priority_queue<long long, vector<long long>, greater<long long>> pq;
        pq.push(splitTime);
        long long ans = 0;
        for (int i = 0; i < (int)timeReq.size(); i++) {
            long long c = pq.top(); pq.pop();
            ans = max(ans, c + timeReq[i]);
            if (i + 1 < (int)timeReq.size()) {
                pq.push(c + splitTime);
                pq.push(c + splitTime);
            }
        }
        return ans;
    }
};

