class Solution {
    public long minTime(int[] timeReq, int splitTime) {
        Arrays.sort(timeReq);
        PriorityQueue<Long> pq = new PriorityQueue<>();
        pq.add((long) splitTime);
        long ans = 0;
        for (int i = timeReq.length - 1; i >= 0; i--) {
            long c = pq.poll();
            ans = Math.max(ans, c + timeReq[i]);
            if (i > 0) {
                pq.add(c + splitTime);
                pq.add(c + splitTime);
            }
        }
        return ans;
    }
}

