var minTime = function(timeReq, splitTime) {
    const t = [...timeReq].sort((a, b) => b - a);
    const h = [splitTime];
    const push = v => {
        h.push(v);
        let i = h.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (h[p] <= h[i]) break;
            [h[p], h[i]] = [h[i], h[p]]; i = p;
        }
    };
    const pop = () => {
        const top = h[0], last = h.pop();
        if (h.length) {
            h[0] = last;
            let i = 0;
            for (;;) {
                let l = 2 * i + 1, r = l + 1, m = i;
                if (l < h.length && h[l] < h[m]) m = l;
                if (r < h.length && h[r] < h[m]) m = r;
                if (m === i) break;
                [h[m], h[i]] = [h[i], h[m]]; i = m;
            }
        }
        return top;
    };
    let ans = 0;
    for (let i = 0; i < t.length; i++) {
        const c = pop();
        ans = Math.max(ans, c + t[i]);
        if (i + 1 < t.length) { push(c + splitTime); push(c + splitTime); }
    }
    return ans;
};
